    <!-- ====== Title bar ====== -->
    <div class="rb-bar">
      <div class="rb-sp"></div>
      <div class="rb-brand">
        <svg class="rb-logo" aria-hidden="true"><use href="#rb-logo" /></svg>
        <h1>Ret<i>IN</i>aBox</h1>
      </div>
      <div class="rb-sp"></div>
      <button
        type="button"
        class="rb-btn"
        style="flex: 0 0 auto"
        @click="loadPreset"
      >
        Load a circuit
      </button>
      <select
        v-model="presetId"
        aria-label="Circuit to load"
        class="rb-bar-select"
      >
        <option value="">-- select --</option>
        <option v-for="p in PRESETS" :key="p.id" :value="p.id">
          {{ p.name }}
        </option>
      </select>
    </div>

    <!-- ====== Tab bar ====== -->
    <div class="rb-tabs" role="tablist">
      <button
        v-for="t in tabs"
        :key="t.mode"
        type="button"
        class="rb-tab"
        role="tab"
        :aria-selected="String(currentMode === t.mode)"
        @click="switchTab(t.mode)"
      >
        {{ t.label }}
      </button>
    </div>

    <!-- ================= Lab ================= -->
    <div v-show="currentMode === 'lab'" class="rb-mode">
      <div class="rb-panels">
        <!-- Panel 1: Stimulus -->
        <section class="rb-panel">
          <p class="rb-title">Visual Stimulus Controller</p>

          <div class="rb-leg">
            <span
              >Unselected:<svg viewBox="0 0 88 104">
                <use href="#led-unselected" /></svg
            ></span>
            <span
              >Selected:<svg viewBox="0 0 88 104">
                <use href="#led-selected" /></svg
            ></span>
            <span
              >Active:<svg viewBox="0 0 88 104"><use href="#led-on" /></svg
            ></span>
          </div>

          <div class="rb-grid" role="group" aria-label="Stimulus LED array">
            <button
              v-for="idx in 9"
              :key="idx"
              type="button"
              class="rb-lamp"
              :aria-pressed="String(isSelected(idx - 1))"
              @click="toggleLamp(idx - 1)"
            >
              <svg viewBox="0 0 88 104"><use :href="lampHref(idx - 1)" /></svg>
              <b>{{ idx }}</b>
            </button>
          </div>

          <div class="rb-btnrow">
            <button type="button" class="rb-btn" @click="selectAll">
              Select all
            </button>
            <button type="button" class="rb-btn" @click="clearAll">
              Clear all
            </button>
          </div>
          <button
            type="button"
            class="rb-run"
            :class="{ 'is-on': running }"
            @click="toggleRun"
          >
            {{
              running ? "Deactivate stimulus LEDs" : "Activate stimulus LEDs"
            }}
          </button>

          <div class="rb-opt">
            <b>Mode:</b>
            <label class="rb-radio">
              <input
                type="radio"
                value="Static"
                :checked="mode === 'Static'"
                @change="setMode('Static')"
              />
              Static
            </label>
            <label class="rb-radio">
              <input
                type="radio"
                value="Motion"
                :checked="mode === 'Motion'"
                @change="setMode('Motion')"
              />
              Motion
            </label>
          </div>
          <div v-show="mode === 'Motion'" class="rb-opt">
            <b>Direction:</b>
            <label class="rb-radio">
              <input
                type="radio"
                value="Left"
                :checked="direction === 'Left'"
                @change="setDirection('Left')"
              />
              Left
            </label>
            <label class="rb-radio">
              <input
                type="radio"
                value="Right"
                :checked="direction === 'Right'"
                @change="setDirection('Right')"
              />
              Right
            </label>
          </div>
          <div v-show="mode === 'Motion'" class="rb-opt">
            <b>Speed:</b>
            <input
              type="range"
              min="0"
              max="2"
              step="1"
              :value="speed"
              style="flex: 1; min-width: 90px"
              @input="setSpeed($event.target.value)"
            />
            <span style="font-size: 0.74rem; min-width: 48px">{{
              speedLabel
            }}</span>
          </div>
        </section>

        <!-- Panel 2: Neurons -->
        <section class="rb-panel">
          <p class="rb-title">Connectivity Manager</p>

          <div class="rb-leg">
            <span>Silent:<i class="sw" style="background: #bdbfb6"></i></span>
            <span
              >Excitatory:<i class="sw" style="background: #cd1916"></i
            ></span>
            <span
              >Inhibitory:<i class="sw" style="background: #1a83c9"></i
            ></span>
            <span
              >Delay:<svg viewBox="0 0 24 24">
                <circle cx="12" cy="12" r="11" fill="none" stroke="#333" />
                <path d="M12 5l6 12H6z" fill="#000" /></svg
            ></span>
          </div>

          <template v-for="k in 2" :key="k">
            <div class="rb-neuron">
              <svg
                :viewBox="'0 0 376 336'"
                role="img"
                :aria-label="'RGC ' + k + ' dendritic field'"
              >
                <use :href="'#rgc-art-' + k" />
                <g class="rb-conn">
                  <g
                    v-for="ch in 9"
                    :key="ch"
                    class="rb-dot"
                    tabindex="0"
                    role="button"
                    :aria-label="dotLabel(k - 1, ch - 1)"
                    @click="cycleDot(k - 1, ch - 1)"
                    @keydown.enter.prevent="cycleDot(k - 1, ch - 1)"
                    @keydown.space.prevent="cycleDot(k - 1, ch - 1)"
                  >
                    <circle
                      class="rb-dot-c"
                      :cx="DOTS[ch - 1][0]"
                      :cy="DOTS[ch - 1][1]"
                      :r="DOT_R"
                      :fill="dotFill(k - 1, ch - 1)"
                    />
                    <path
                      class="rb-dot-t"
                      :d="
                        'M' +
                        DOTS[ch - 1][0] +
                        ' ' +
                        (DOTS[ch - 1][1] - 6) +
                        'l6.5 11h-13z'
                      "
                      fill="#000"
                      :style="{
                        display: dotHasDelay(k - 1, ch - 1) ? '' : 'none',
                      }"
                    />
                  </g>
                </g>
              </svg>
            </div>
            <div class="rb-opt">
              <b>Threshold:</b>
              <input
                class="rb-num"
                type="number"
                min="0"
                max="9"
                step="1"
                :value="rgcThreshold(k - 1)"
                @change="setThreshold(k - 1, $event)"
              />
              <button
                type="button"
                class="rb-btn"
                style="flex: 0 0 auto; padding: 0.2rem 0.5rem"
                @click="openModal(k - 1)"
              >
                Delays&hellip;
              </button>
            </div>
            <div class="rb-opt">
              <b>Type:</b>
              <label class="rb-radio">
                <input
                  type="radio"
                  :value="'ON'"
                  :name="'rb-pol-' + (k - 1)"
                  :checked="rgcPolarity(k - 1) === 'ON'"
                  @change="setPolarity(k - 1, 'ON')"
                />
                ON
              </label>
              <label class="rb-radio">
                <input
                  type="radio"
                  :value="'OFF'"
                  :name="'rb-pol-' + (k - 1)"
                  :checked="rgcPolarity(k - 1) === 'OFF'"
                  @change="setPolarity(k - 1, 'OFF')"
                />
                OFF
              </label>
            </div>
            <hr v-if="k === 1" class="rb-sep" />
          </template>
        </section>

        <!-- Panel 3: Signal Monitor -->
        <section class="rb-panel">
          <p class="rb-title">Signal Monitor</p>
          <div class="rb-leg">
            <span
              ><i class="bar" style="background: #cd1916"></i>Excitatory</span
            >
            <span
              ><i class="bar" style="background: #1a83c9"></i>Inhibitory</span
            >
          </div>
          <div class="rb-scope">
            <canvas
              ref="scopeCanvas"
              role="img"
              aria-label="Rolling ten second recording of photoreceptor input, synaptic drive and ganglion cell output"
            ></canvas>
          </div>
        </section>
      </div>
    </div>

    <!-- ================= Code Breaker ================= -->
    <div v-show="currentMode === 'cb'" class="rb-mode">
      <div style="padding: 0.6rem 0.8rem 0">
        <label style="font-size: 0.8rem"
          >Challenge:
          <select
            v-model="cbChallengeName"
            @change="cbLoad(cbChallengeName)"
            style="
              font-size: 0.8rem;
              padding: 0.2rem;
              border: 1px solid rgb(var(--color-mute));
              border-radius: 4px;
            "
          >
            <option v-for="name in cbChallengeNames" :key="name" :value="name">
              {{ name }}
            </option>
          </select>
        </label>
      </div>
      <div class="rb-cb">
        <div class="rb-box">
          <h3>Secret Code</h3>
          <div class="rb-code">
            <template v-for="(tok, ti) in cbTokens" :key="ti">
              <div v-if="tok.type === 'space'" class="rb-tok sp">&nbsp;</div>
              <div
                v-else-if="tok.type === 'letter'"
                class="rb-tok"
                :data-answer="tok.answer"
              >
                <div class="rb-pat">
                  <i
                    v-for="(v, pi) in tok.pattern"
                    :key="pi"
                    :class="{ on: v }"
                  ></i>
                </div>
                <select
                  v-model="cbAnswers[ti]"
                  aria-label="Letter for this pattern"
                  :class="cbSelectClass(ti)"
                >
                  <option value=""></option>
                  <option v-for="L in cbLetters" :key="L" :value="L">
                    {{ L }}
                  </option>
                </select>
              </div>
              <div v-else class="rb-tok">
                <b>{{ tok.text }}</b>
              </div>
            </template>
          </div>
        </div>
        <div>
          <div class="rb-box">
            <h3>Cipher</h3>
            <div class="rb-cipher">
              <figure v-for="(pref, pi) in cbPrefStim" :key="pi">
                <div class="rb-pat">
                  <i
                    v-for="(v, vi) in pref.stim"
                    :key="vi"
                    :class="{ on: v }"
                  ></i>
                </div>
                {{ pref.label }}
              </figure>
            </div>
            <table class="rb-book">
              <thead>
                <tr>
                  <th>RGC1</th>
                  <th>RGC2</th>
                  <th>Letter</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="row in cbBook" :key="row[2]">
                  <td>{{ row[0] }}</td>
                  <td>{{ row[1] }}</td>
                  <td>{{ row[2] }}</td>
                </tr>
              </tbody>
            </table>
          </div>
          <button type="button" class="rb-dmtest" @click="cbCheck">
            Check Answers
          </button>
          <p class="rb-result" :class="cbResultClass">{{ cbResult }}</p>
        </div>
      </div>
    </div>

    <!-- ================= Discovery Mode ================= -->
    <div v-show="currentMode === 'dm'" class="rb-mode">
      <div class="rb-dm">
        <div class="rb-dmbar">
          <span>Current Challenge:</span>
          <select v-model="dmChallengeName" @change="dmReset">
            <option v-for="name in dmChallengeNames" :key="name" :value="name">
              {{ name }}
            </option>
          </select>
          <button type="button" :disabled="!!dmChallenge" @click="dmStart">
            {{ dmChallenge ? "Challenge Running" : "Start Challenge" }}
          </button>
          <span
            >Points: <b class="val">{{ dmPoints }}</b></span
          >
          <span
            >Timer: <b class="val">{{ dmTimer }}</b></span
          >
        </div>

        <div class="rb-dmtop">
          <div class="rb-box">
            <h3>Instructions</h3>
            <p style="font-size: 0.76rem; margin: 0">
              1. Select and start a challenge from the menu above.<br />
              2. Complete phases 1 and 2.<br /><br />
              Tip: watch the live RGC response to guide your progress.
            </p>
          </div>
          <div class="rb-box">
            <h3>Live RGC Response</h3>
            <canvas
              ref="dmCanvas"
              style="width: 100%; height: auto; display: block"
              role="img"
              aria-label="Live RGC response"
            ></canvas>
          </div>
        </div>

        <div class="rb-dmphases">
          <!-- Phase 1 -->
          <div class="rb-phase" :data-locked="dmPhase1Locked ? '1' : '0'">
            <h3>Phase 1: Discover the Preferred Stimulus</h3>
            <div class="rb-dmgrid">
              <button
                v-for="i in 9"
                :key="i"
                type="button"
                :aria-pressed="String(!!dmStim[i - 1])"
                @click="dmToggleStim(i - 1)"
              >
                {{ i }}
              </button>
            </div>
            <div class="rb-opt">
              <b>Motion:</b>
              <select v-model="dmMotionType" @change="dmMotionChanged">
                <option>Static</option>
                <option>Moving</option>
              </select>
            </div>
            <div class="rb-opt">
              <b>Speed:</b>
              <select
                v-model="dmSpeedSel"
                :disabled="dmMotionType === 'Static'"
                @change="dmApplyStim"
              >
                <option v-for="o in dmSpeedOpts" :key="o">{{ o }}</option>
              </select>
            </div>
            <div class="rb-opt">
              <b>Direction:</b>
              <select
                v-model="dmDirSel"
                :disabled="dmMotionType === 'Static'"
                @change="dmApplyStim"
              >
                <option v-for="o in dmDirOpts" :key="o">{{ o }}</option>
              </select>
            </div>
            <button type="button" class="rb-dmtest" @click="dmTestStim">
              Test Stimulus
            </button>
            <p class="rb-dmnote" :class="dmNote1Class">{{ dmNote1 }}</p>
          </div>

          <!-- Phase 2 -->
          <div class="rb-phase" :data-locked="dmPhase2Locked ? '1' : '0'">
            <h3>Phase 2: Discover the Circuit Connectivity</h3>
            <div class="rb-leg">
              <span>Silent:<i class="sw" style="background: #bdbfb6"></i></span>
              <span
                >Excitatory:<i class="sw" style="background: #cd1916"></i
              ></span>
              <span
                >Inhibitory:<i class="sw" style="background: #1a83c9"></i
              ></span>
            </div>
            <div class="rb-neuron">
              <svg viewBox="0 0 404 352" role="img" aria-label="Your circuit">
                <use href="#rgc-art-M" />
                <g class="rb-conn">
                  <g
                    v-for="ch in 9"
                    :key="ch"
                    class="rb-dot"
                    tabindex="0"
                    role="button"
                    @click="dmCycleDot(ch - 1)"
                    @keydown.enter.prevent="dmCycleDot(ch - 1)"
                    @keydown.space.prevent="dmCycleDot(ch - 1)"
                  >
                    <circle
                      class="rb-dot-c"
                      :cx="DOTS[ch - 1][0]"
                      :cy="DOTS[ch - 1][1]"
                      :r="DOT_R"
                      :fill="dmDotFill(ch - 1)"
                    />
                    <path
                      class="rb-dot-t"
                      :d="
                        'M' +
                        DOTS[ch - 1][0] +
                        ' ' +
                        (DOTS[ch - 1][1] - 6) +
                        'l6.5 11h-13z'
                      "
                      fill="#000"
                      :style="{ display: dmDotHasDelay(ch - 1) ? '' : 'none' }"
                    />
                  </g>
                </g>
              </svg>
            </div>
            <div class="rb-opt">
              <b>Threshold:</b>
              <input
                class="rb-num"
                type="number"
                min="0"
                max="9"
                v-model.number="dmThr"
              />
              <button
                type="button"
                class="rb-btn"
                style="flex: 0 0 auto; padding: 0.2rem 0.5rem"
                @click="dmOpenDelays"
              >
                Delays&hellip;
              </button>
            </div>
            <div class="rb-opt">
              <b>Type:</b>
              <label class="rb-radio"
                ><input type="radio" value="ON" v-model="dmPol" /> ON</label
              >
              <label class="rb-radio"
                ><input type="radio" value="OFF" v-model="dmPol" /> OFF</label
              >
            </div>
            <button type="button" class="rb-dmtest" @click="dmTestConn">
              Test Connectivity
            </button>
            <p class="rb-dmnote" :class="dmNote2Class">{{ dmNote2 }}</p>
          </div>
        </div>
      </div>
    </div>

    <!-- ================= Lesson Plans ================= -->
    <div v-show="currentMode === 'lp'" class="rb-mode rb-doc">
      <div class="rb-docbar">
        <h3>RetINaBox Lesson Plans</h3>
        <div class="sp"></div>
        <a
          class="primary"
          :href="lpUrl + '#view=FitH'"
          target="_blank"
          rel="noopener"
          >Open in new tab</a
        >
        <a :href="lpGhUrl" target="_blank" rel="noopener">View on GitHub</a>
      </div>
      <div class="rb-frame" ref="lpFrame">
        <p v-if="!lpMounted" class="note">Loading&hellip;</p>
        <iframe
          v-if="lpMounted"
          title="RetINaBox lesson plans"
          :src="lpUrl + '#view=FitH'"
          @load="lpLoaded = true"
        ></iframe>
      </div>
      <p class="rb-dochint">
        Four lessons plus full solutions. Open it in a new tab to keep it beside
        the GUI while you work, or if it does not display here.
      </p>
    </div>

    <!-- ================= Teaching Slides ================= -->
    <div v-show="currentMode === 'sl'" class="rb-mode rb-doc">
      <div class="rb-docbar">
        <h3>RetINaBox Teaching Slides</h3>
        <div class="sp"></div>
        <a
          class="primary"
          :href="slUrl + '#view=FitH'"
          target="_blank"
          rel="noopener"
          >Open in new tab</a
        >
        <a :href="slGhUrl" target="_blank" rel="noopener">View on GitHub</a>
      </div>
      <div class="rb-frame" ref="slFrame">
        <p v-if="!slMounted" class="note">Loading&hellip;</p>
        <iframe
          v-if="slMounted"
          title="RetINaBox teaching slides"
          :src="slUrl + '#view=FitH'"
          @load="slLoaded = true"
        ></iframe>
      </div>
      <p class="rb-dochint">
        Slide deck for the four lessons. Open it in a new tab to keep it beside
        the GUI while you work, or if it does not display here.
      </p>
    </div>

    <!-- ====== Connectivity / Delay Modal ====== -->
    <div
      v-show="modalOpen"
      class="rb-modal"
      role="dialog"
      aria-modal="true"
      @click.self="modalOpen = false"
    >
      <div class="rb-sheet">
        <h2>{{ modalTitle }} Connectivity</h2>
        <div class="rb-units">
          <div v-for="ch in 9" :key="ch" class="rb-unit">
            <button
              type="button"
              class="rb-pm"
              :data-state="modalConnState(ch - 1)"
              @click="modalCycle(ch - 1)"
            >
              {{
                modalConnState(ch - 1) === "excitatory"
                  ? "+"
                  : modalConnState(ch - 1) === "inhibitory"
                    ? "\u2212"
                    : ""
              }}
            </button>
            <label>Delay</label>
            <input
              type="range"
              min="0"
              max="3"
              step="1"
              :value="modalDelayIdx(ch - 1)"
              :disabled="modalConnState(ch - 1) === 'off'"
              @input="modalSetDelay(ch - 1, $event.target.value)"
            />
            <small>{{ modalDelayMs(ch - 1) }} ms</small>
          </div>
        </div>
        <button type="button" class="rb-close" @click="modalOpen = false">
          Done
        </button>
      </div>
    </div>

    <!-- ====== Footer ====== -->
    <div class="rb-foot">
      Web edition of <b>RetINaBox</b> (Trenholm Lab). Artwork and circuit model
      from the desktop application &mdash; hardware build files, lesson plans
      and source:
      <a href="https://github.com/Trenholm-Lab/RetINaBox"
        >github.com/Trenholm-Lab/RetINaBox</a
      >.
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount } from "vue";
import {
  DT_MS,
  DELAY_MS,
  DELAY_KEYS,
  STATES,
  SPEED_NAMES,
  grid,
  blankConn,
  createModel,
  clearTraces,
  armStimulus,
  tick,
  PRESETS,
  COL,
  DOTS,
  DOT_R,
  SCOPE,
  drawScope,
  drawDmTrace,
  cbTokenize,
  CB_DEFAULT,
  DM_DEFAULT,
  cdnURL,
  ghURL,
  DOC_FILES,
} from "@/helper/retinabox";

/* ================================================================
   NON-REACTIVE model state — TypedArrays must NOT be Vue-proxied
   ================================================================ */
let M = createModel();
let dmModel = createModel();

/* ================================================================
   REACTIVE UI STATE
   ================================================================ */
const currentMode = ref("lab");
const presetId = ref("");
const uiTick = ref(0);

// Template refs
const rootEl = ref(null);
const scopeCanvas = ref(null);
const dmCanvas = ref(null);
const lpFrame = ref(null);
const slFrame = ref(null);

// Tabs
const tabs = [
  { mode: "lab", label: "RetINaBox Lab" },
  { mode: "cb", label: "Code Breaker" },
  { mode: "dm", label: "Discovery Mode" },
  { mode: "lp", label: "Lesson Plans" },
  { mode: "sl", label: "Teaching Slides" },
];

/* ---- Lab computed (read from M via uiTick bridge) ---- */
const running = computed(() => {
  uiTick.value;
  return M.running;
});
const mode = computed(() => {
  uiTick.value;
  return M.mode;
});
const direction = computed(() => {
  uiTick.value;
  return M.direction;
});
const speed = computed(() => {
  uiTick.value;
  return M.speed;
});
const speedLabel = computed(() => SPEED_NAMES[speed.value]);

/* ---- Modal state ---- */
const modalOpen = ref(false);
const modalTitle = ref("");
let modalConn = null;
let modalOnChange = null;
const modalTick = ref(0);

/* ---- Document viewers ---- */
const lpMounted = ref(false);
const lpLoaded = ref(false);
const slMounted = ref(false);
const slLoaded = ref(false);
const lpUrl = cdnURL(DOC_FILES.lp);
const lpGhUrl = ghURL(DOC_FILES.lp);
const slUrl = cdnURL(DOC_FILES.sl);
const slGhUrl = ghURL(DOC_FILES.sl);

/* ---- Code Breaker state ---- */
const cbChallengeNames = Object.keys(CB_DEFAULT);
const cbChallengeName = ref(cbChallengeNames[0]);
const cbLetters = ref([]);
const cbTokens = ref([]);
const cbAnswers = reactive({});
const cbPrefStim = ref([]);
const cbBook = ref([]);
const cbResult = ref("");
const cbResultClass = ref("");
const cbChecked = ref(false);

/* ---- Discovery Mode state ---- */
const dmChallengeNames = Object.keys(DM_DEFAULT);
const dmChallengeName = ref(dmChallengeNames[0]);
const dmChallenge = ref(null);
const dmPoints = ref(100);
const dmTimer = ref("00:00");
const dmStim = reactive([0, 0, 0, 0, 0, 0, 0, 0, 0]);
const dmUser = blankConn();
const dmDotTick = ref(0);
const dmMotionType = ref("Static");
const dmSpeedSel = ref("---");
const dmDirSel = ref("---");
const dmSpeedOpts = ref(["---"]);
const dmDirOpts = ref(["---"]);
const dmPhase1Locked = ref(true);
const dmPhase2Locked = ref(true);
const dmNote1 = ref("");
const dmNote1Class = ref("");
const dmNote2 = ref("");
const dmNote2Class = ref("");
const dmThr = ref(1);
const dmPol = ref("ON");
let dmT0 = 0;
let dmTimerInterval = null;

/* ================================================================
   rAF LOOP
   ================================================================ */
let scopeCtx = null;
let dmCtx = null;
let scopeCW = 600;
let dmCW = 400;
const DMH = 76;
let last = 0;
let acc = 0;
let rafId = null;
let dpr = 1;
let font = "10px sans-serif";

function frame(now) {
  if (!last) last = now;
  acc += now - last;
  last = now;
  if (acc > 500) acc = 500;
  while (acc >= DT_MS) {
    tick(M);
    tick(dmModel);
    acc -= DT_MS;
  }
  uiTick.value++;
  if (currentMode.value === "lab" && scopeCtx) {
    drawScope(scopeCtx, M, scopeCW);
  } else if (currentMode.value === "dm" && dmCtx) {
    drawDmTrace(dmCtx, dmModel, dmCW, DMH, font, !!dmChallenge.value);
  }
  rafId = requestAnimationFrame(frame);
}

/* ================================================================
   CANVAS RESIZE
   ================================================================ */
function resizeScope() {
  const canvas = scopeCanvas.value;
  if (!canvas || !canvas.parentNode) return;
  const w = Math.max(canvas.parentNode.clientWidth, 300);
  scopeCW = w;
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(scopeCW * dpr);
  canvas.height = Math.round(SCOPE.CH * dpr);
  canvas.style.height = SCOPE.CH + "px";
  if (rootEl.value) {
    font = "10px " + getComputedStyle(rootEl.value).fontFamily;
  }
  scopeCtx = canvas.getContext("2d");
  scopeCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
}

function resizeDm() {
  const canvas = dmCanvas.value;
  if (!canvas || !canvas.parentNode) return;
  const w = Math.max(canvas.parentNode.clientWidth, 200);
  dmCW = w;
  const d = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(dmCW * d);
  canvas.height = Math.round(DMH * d);
  canvas.style.height = DMH + "px";
  dmCtx = canvas.getContext("2d");
  dmCtx.setTransform(d, 0, 0, d, 0, 0);
}

function onResize() {
  if (currentMode.value === "lab") resizeScope();
  else if (currentMode.value === "dm") resizeDm();
}

/* ================================================================
   LAB ACTIONS
   ================================================================ */
function isSelected(idx) {
  uiTick.value;
  const r = (idx / 3) | 0;
  const c = idx % 3;
  return M.selected[r][c];
}

function lampHref(idx) {
  uiTick.value;
  const r = (idx / 3) | 0;
  const c = idx % 3;
  if (M.activated[r][c]) return "#led-on";
  if (M.selected[r][c]) return "#led-selected";
  return "#led-unselected";
}

function toggleLamp(idx) {
  const r = (idx / 3) | 0;
  const c = idx % 3;
  M.selected[r][c] = !M.selected[r][c];
  if (M.running) armStimulus(M);
}

function selectAll() {
  M.selected = grid(true);
  if (M.running) armStimulus(M);
}

function clearAll() {
  M.selected = grid(false);
  if (M.running) armStimulus(M);
}

function toggleRun() {
  M.running = !M.running;
  armStimulus(M);
}

function setMode(val) {
  M.mode = val;
  if (M.running) armStimulus(M);
}

function setDirection(val) {
  M.direction = val;
}

function setSpeed(val) {
  M.speed = +val;
}

function loadPreset() {
  const id = presetId.value;
  if (!id) return;
  const p = PRESETS.find((q) => q.id === id);
  if (!p) return;
  p.apply(M);
  M.running = true;
  armStimulus(M);
  clearTraces(M);
}

/* ---- Neuron dot helpers ---- */
function dotFill(k, ch) {
  uiTick.value;
  const cell = M.rgc[k].conn[(ch / 3) | 0][ch % 3];
  if (cell.state === "excitatory") return COL.red;
  if (cell.state === "inhibitory") return COL.blue;
  return COL.gray;
}

function dotHasDelay(k, ch) {
  uiTick.value;
  return M.rgc[k].conn[(ch / 3) | 0][ch % 3].delay !== "None";
}

function dotLabel(k, ch) {
  uiTick.value;
  const cell = M.rgc[k].conn[(ch / 3) | 0][ch % 3];
  return (
    "Input " +
    (ch + 1) +
    ": " +
    cell.state +
    ", delay " +
    DELAY_MS[cell.delay] +
    " ms"
  );
}

function cycleDot(k, ch) {
  const cell = M.rgc[k].conn[(ch / 3) | 0][ch % 3];
  cell.state = STATES[(STATES.indexOf(cell.state) + 1) % 3];
  if (cell.state === "off") cell.delay = "None";
}

function rgcThreshold(k) {
  uiTick.value;
  return M.rgc[k].threshold;
}

function rgcPolarity(k) {
  uiTick.value;
  return M.rgc[k].polarity;
}

function setThreshold(k, e) {
  const v = Math.max(0, Math.min(9, Math.round(+e.target.value || 0)));
  e.target.value = v;
  M.rgc[k].threshold = v;
}

function setPolarity(k, val) {
  M.rgc[k].polarity = val;
}

/* ================================================================
   MODAL
   ================================================================ */
function openModal(k) {
  openModalFor("RGC " + (k + 1), M.rgc[k].conn, () => {});
}

function openModalFor(title, connObj, onChange) {
  modalTitle.value = title;
  modalConn = connObj;
  modalOnChange = onChange;
  modalTick.value++;
  modalOpen.value = true;
}

function modalConnState(ch) {
  modalTick.value;
  if (!modalConn) return "off";
  return modalConn[(ch / 3) | 0][ch % 3].state;
}

function modalDelayIdx(ch) {
  modalTick.value;
  if (!modalConn) return 0;
  return DELAY_KEYS.indexOf(modalConn[(ch / 3) | 0][ch % 3].delay);
}

function modalDelayMs(ch) {
  modalTick.value;
  if (!modalConn) return 0;
  return DELAY_MS[modalConn[(ch / 3) | 0][ch % 3].delay];
}

function modalCycle(ch) {
  if (!modalConn) return;
  const cell = modalConn[(ch / 3) | 0][ch % 3];
  cell.state = STATES[(STATES.indexOf(cell.state) + 1) % 3];
  if (cell.state === "off") {
    cell.delay = "None";
  }
  modalTick.value++;
  if (modalOnChange) modalOnChange();
}

function modalSetDelay(ch, val) {
  if (!modalConn) return;
  const cell = modalConn[(ch / 3) | 0][ch % 3];
  cell.delay = DELAY_KEYS[+val];
  modalTick.value++;
  if (modalOnChange) modalOnChange();
}

function onEscape(e) {
  if (e.key === "Escape") modalOpen.value = false;
}

/* ================================================================
   CODE BREAKER
   ================================================================ */
function cbLoad(name) {
  const d = CB_DEFAULT[name];
  if (!d) return;
  const letters = d.RetinaBox_output;
  cbLetters.value = letters;
  const pool = JSON.parse(JSON.stringify(d.stim_codes));
  const rawToks = cbTokenize(d.Solution_string, letters);

  const tokens = [];
  for (const tk of rawToks) {
    if (tk === " ") {
      tokens.push({ type: "space" });
    } else if (letters.some((L) => L.toUpperCase() === tk.toUpperCase())) {
      const up = tk.toUpperCase();
      const arr =
        pool[up] && pool[up].length
          ? pool[up].shift()
          : [0, 0, 0, 0, 0, 0, 0, 0, 0];
      tokens.push({ type: "letter", answer: up, pattern: arr });
    } else {
      tokens.push({ type: "punct", text: tk });
    }
  }
  cbTokens.value = tokens;

  // Reset answers
  for (const key of Object.keys(cbAnswers)) delete cbAnswers[key];

  cbPrefStim.value = [
    { stim: d.RGC_1_pref_stim, label: "RGC 1" },
    { stim: d.RGC_2_pref_stim, label: "RGC 2" },
  ];

  cbBook.value = [
    ["0", "0", letters[0]],
    ["1", "0", letters[1]],
    ["0", "1", letters[2]],
    ["1", "1", letters[3]],
  ];

  cbResult.value = "";
  cbResultClass.value = "";
  cbChecked.value = false;
}

function cbSelectClass(ti) {
  if (!cbChecked.value) return "";
  const tok = cbTokens.value[ti];
  if (!tok || tok.type !== "letter") return "";
  const v = cbAnswers[ti];
  if (!v) return "";
  return v === tok.answer ? "ok" : "no";
}

function cbCheck() {
  cbChecked.value = true;
  let total = 0;
  let right = 0;
  cbTokens.value.forEach((tok, i) => {
    if (tok.type !== "letter") return;
    total++;
    if (cbAnswers[i] === tok.answer) right++;
  });
  cbResult.value = "Correct letters: " + right + " / " + total;
  cbResultClass.value = right === total ? "rb-ok" : "rb-no";
}

/* ================================================================
   DISCOVERY MODE
   ================================================================ */
function dmSolutions(name) {
  const d = DM_DEFAULT[name];
  return Array.isArray(d) ? d : [d];
}

function dmLoadHidden(name) {
  const sol = dmSolutions(name)[0];
  const flat = sol.connectivity;
  const cn = blankConn();
  for (let ch = 0; ch < 9; ch++) {
    cn[(ch / 3) | 0][ch % 3] = { state: flat[ch].state, delay: flat[ch].delay };
  }
  dmModel.rgc[0] = {
    polarity: sol.polarity || "ON",
    threshold: sol.threshold,
    conn: cn,
  };
  dmModel.rgc[1] = { polarity: "ON", threshold: 1, conn: blankConn() };
  clearTraces(dmModel);
}

function dmApplyStim() {
  for (let r = 0; r < 3; r++)
    for (let c = 0; c < 3; c++) dmModel.selected[r][c] = !!dmStim[r * 3 + c];
  dmModel.mode = dmMotionType.value === "Moving" ? "Motion" : "Static";
  dmModel.speed = { Slow: 0, Medium: 1, Fast: 2 }[dmSpeedSel.value] || 0;
  dmModel.direction =
    dmDirSel.value === "Left" || dmDirSel.value === "Right"
      ? dmDirSel.value
      : "Right";
  dmModel.running = !!dmChallenge.value;
  armStimulus(dmModel);
}

function dmToggleStim(i) {
  dmStim[i] = dmStim[i] ? 0 : 1;
  dmApplyStim();
}

function dmMotionChanged() {
  if (dmMotionType.value === "Static") {
    dmSpeedOpts.value = ["---"];
    dmDirOpts.value = ["---"];
    dmSpeedSel.value = "---";
    dmDirSel.value = "---";
  } else {
    dmSpeedOpts.value = ["Slow", "Medium", "Fast"];
    dmDirOpts.value = ["Left", "Right"];
    dmSpeedSel.value = "Slow";
    dmDirSel.value = "Right";
  }
  dmApplyStim();
}

function dmStart() {
  dmChallenge.value = dmChallengeName.value;
  dmLoadHidden(dmChallenge.value);
  dmApplyStim();
  dmPhase1Locked.value = false;
  dmPhase2Locked.value = true;
  dmNote1.value = "";
  dmNote1Class.value = "";
  dmNote2.value = "";
  dmNote2Class.value = "";
  dmT0 = Date.now();
  if (dmTimerInterval) clearInterval(dmTimerInterval);
  dmTimerInterval = setInterval(() => {
    const e = Math.floor((Date.now() - dmT0) / 1000);
    dmTimer.value =
      String(Math.floor(e / 60)).padStart(2, "0") +
      ":" +
      String(e % 60).padStart(2, "0");
  }, 250);
}

function dmReset() {
  dmChallenge.value = null;
  if (dmTimerInterval) {
    clearInterval(dmTimerInterval);
    dmTimerInterval = null;
  }
  dmTimer.value = "00:00";
  dmPhase1Locked.value = true;
  dmPhase2Locked.value = true;
  for (let i = 0; i < 9; i++) dmStim[i] = 0;
  for (let r = 0; r < 3; r++)
    for (let c = 0; c < 3; c++) dmUser[r][c] = { state: "off", delay: "None" };
  dmDotTick.value++;
  dmMotionType.value = "Static";
  dmSpeedOpts.value = ["---"];
  dmDirOpts.value = ["---"];
  dmSpeedSel.value = "---";
  dmDirSel.value = "---";
  dmNote1.value = "";
  dmNote1Class.value = "";
  dmNote2.value = "";
  dmNote2Class.value = "";
  clearTraces(dmModel);
  dmApplyStim();
}

function dmLose(noteRef, noteClassRef) {
  dmPoints.value = Math.max(0, dmPoints.value - 5);
  noteRef.value = "Not yet \u2014 you lost 5 points. Try again.";
  noteClassRef.value = "rb-dmnote rb-no";
}

function dmTestStim() {
  if (!dmChallenge.value) return;
  if (dmStim.every((v) => !v)) {
    dmNote1.value = "Select at least one stimulus position.";
    dmNote1Class.value = "rb-dmnote";
    return;
  }
  const uMot = dmMotionType.value.toLowerCase();
  const uSpd = dmSpeedSel.value.toLowerCase();
  const uDir = dmDirSel.value.toLowerCase();
  const hit = dmSolutions(dmChallenge.value).some((k) => {
    const kd = k.direction === "" ? "---" : k.direction.toLowerCase();
    const ks = k.speed === "" ? "---" : k.speed.toLowerCase();
    return (
      k.stim_array.every((v, i) => !!v === !!dmStim[i]) &&
      k.motion_type.toLowerCase() === uMot &&
      kd === uDir &&
      ks === uSpd
    );
  });
  if (hit) {
    dmNote1.value = "Correct stimulus. Proceed to Phase 2.";
    dmNote1Class.value = "rb-dmnote rb-ok";
    dmPhase1Locked.value = true;
    dmPhase2Locked.value = false;
  } else {
    dmLose(dmNote1, dmNote1Class);
  }
}

function dmTestConn() {
  if (!dmChallenge.value) return;
  const flat = [];
  for (let ch = 0; ch < 9; ch++) flat.push(dmUser[(ch / 3) | 0][ch % 3]);
  if (flat.every((c) => c.state === "off")) {
    dmNote2.value = "Configure at least one photoreceptor.";
    dmNote2Class.value = "rb-dmnote";
    return;
  }
  const uMot = dmMotionType.value.toLowerCase();
  const uSpd = dmSpeedSel.value.toLowerCase();
  const uDir = dmDirSel.value.toLowerCase();
  const hit = dmSolutions(dmChallenge.value).some((k) => {
    const kd = k.direction === "" ? "---" : k.direction.toLowerCase();
    const ks = k.speed === "" ? "---" : k.speed.toLowerCase();
    return (
      k.connectivity.every(
        (c, i) => c.state === flat[i].state && c.delay === flat[i].delay
      ) &&
      k.threshold === dmThr.value &&
      (k.polarity || "ON") === dmPol.value &&
      k.stim_array.every((v, i) => !!v === !!dmStim[i]) &&
      k.motion_type.toLowerCase() === uMot &&
      kd === uDir &&
      ks === uSpd
    );
  });
  if (hit) {
    dmNote2.value = "Correct connectivity. Challenge completed.";
    dmNote2Class.value = "rb-dmnote rb-ok";
    dmPhase2Locked.value = true;
    if (dmTimerInterval) {
      clearInterval(dmTimerInterval);
      dmTimerInterval = null;
    }
    dmChallenge.value = null;
  } else {
    dmLose(dmNote2, dmNote2Class);
  }
}

/* DM dot helpers */
function dmDotFill(ch) {
  dmDotTick.value;
  uiTick.value;
  const c = dmUser[(ch / 3) | 0][ch % 3];
  if (c.state === "excitatory") return COL.red;
  if (c.state === "inhibitory") return COL.blue;
  return COL.gray;
}

function dmDotHasDelay(ch) {
  dmDotTick.value;
  uiTick.value;
  return dmUser[(ch / 3) | 0][ch % 3].delay !== "None";
}

function dmCycleDot(ch) {
  const c = dmUser[(ch / 3) | 0][ch % 3];
  c.state = STATES[(STATES.indexOf(c.state) + 1) % 3];
  if (c.state === "off") c.delay = "None";
  dmDotTick.value++;
}

function dmOpenDelays() {
  openModalFor("Your circuit", dmUser, () => {
    dmDotTick.value++;
  });
}

/* ================================================================
   TAB SWITCHING
   ================================================================ */
function switchTab(m) {
  currentMode.value = m;
  if (m === "lab") {
    requestAnimationFrame(() => resizeScope());
  }
  if (m === "dm") {
    requestAnimationFrame(() => resizeDm());
  }
  if (m === "lp" && !lpMounted.value) {
    lpMounted.value = true;
  }
  if (m === "sl" && !slMounted.value) {
    slMounted.value = true;
  }
}

/* ================================================================
   LIFECYCLE
   ================================================================ */
onMounted(() => {
  // Boot: clean start
  M.running = false;
  M.mode = "Static";
  M.selected = grid(false);
  armStimulus(M);
  clearTraces(M);

  // Canvas setup
  resizeScope();
  resizeDm();
  window.addEventListener("resize", onResize);
  document.addEventListener("keydown", onEscape);

  // Code Breaker init
  cbLoad(cbChallengeName.value);

  // Start rAF
  rafId = requestAnimationFrame(frame);
});

onBeforeUnmount(() => {
  if (rafId) cancelAnimationFrame(rafId);
  window.removeEventListener("resize", onResize);
  document.removeEventListener("keydown", onEscape);
  if (dmTimerInterval) clearInterval(dmTimerInterval);
});
</script>

